Outcome<SocialCatalog> decode_social_catalog(const BoundaryValue& data){try{using namespace boundary;SocialCatalog result;for(auto& row:object(field(data,"actors","data"),"actors")){auto* value=row.second.find("social");if(!value)continue;fields(*value,{"kind","target_actor_id","food_item_id","interval_ticks","share_news"},{},row.first);result.policies.insert(row.first,{get_string(*value,"kind",row.first),get_string(*value,"target_actor_id",row.first),get_string(*value,"food_item_id",row.first),get_int(*value,"interval_ticks",row.first),get_bool(*value,"share_news",row.first)});auto* policy=result.policies.find(row.first);if((policy->kind!="cooperative"&&policy->kind!="selfish")||policy->interval_ticks<1||policy->interval_ticks>120||!field(data,"actors","data").find(policy->target_actor_id)||!field(data,"items","data").find(policy->food_item_id))fail("InvalidSocialPolicy",row.first);}return {true,std::move(result),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<SocialState> decode_social_seed(const BoundaryValue& world,Integer selected_version){try{using namespace boundary;if(selected_version!=1&&selected_version!=2)unsupported("UnsupportedOriginalSocialVersion",{});SocialState s;s.original_relation_version=selected_version;for(auto& row:object(field(world,"relations",""),"relations")){auto& r=row.second;fields(r,{"from_actor","to_actor","trust","affinity"},{"id"},row.first);RelationRecord relation;relation.field_order=order(r);relation.from_actor=get_string(r,"from_actor",row.first);relation.to_actor=get_string(r,"to_actor",row.first);relation.trust=get_int(r,"trust",row.first);relation.affinity=get_int(r,"affinity",row.first);if(auto* id=r.find("id"))relation.id=string(*id,row.first);s.relations.insert(row.first,std::move(relation));}auto& social=field(world,"social","");if(selected_version==1)fields(social,{"last_tick","memories","events"},{"dynamic"},"social");else fields(social,{"last_tick","memories","events","relation_results"},{"dynamic"},"social");s.last_tick=get_int(social,"last_tick","social");s.field_order=order(social);if(auto* dynamic=social.find("dynamic")){ScopedCheckpointJsonDecode dynamic_scope(CheckpointWorldJsonSection::dynamic_social);const auto version=get_int(*dynamic,"version","dynamic_social");auto parsed=social_time2_version(version)?decode_dynamic_social_time2(*dynamic):decode_dynamic_social(*dynamic);if(!parsed.ok)return {false,{},parsed.error};s.dynamic=std::move(parsed.value);}for(auto& row:object(field(social,"memories","social"),"social/memories")){OrderedTable<SocialMemory> memories;for(auto& r:object(row.second,row.first)){fields(r.second,{"learned_tick","source_actor_id"},{},r.first);memories.insert(r.first,{get_int(r.second,"learned_tick",r.first),get_string(r.second,"source_actor_id",r.first),order(r.second)});}s.memories.insert(row.first,std::move(memories));}for(auto& row:object(field(social,"events","social"),"social/events")){auto& r=row.second;if(selected_version==1)fields(r,{"id","kind","tick","place_id","actor_id","target_actor_id","item_id","quantity","reason","fact_id"},{},row.first);else fields(r,{"id","kind","tick","place_id","actor_id","target_actor_id","item_id","quantity","reason","fact_id","original_application"},{},row.first);s.events.insert(row.first,{get_string(r,"id",row.first),get_string(r,"kind",row.first),get_int(r,"tick",row.first),get_string(r,"place_id",row.first),get_string(r,"actor_id",row.first),get_string(r,"target_actor_id",row.first),get_string(r,"item_id",row.first),get_int(r,"quantity",row.first),get_string(r,"reason",row.first),get_string(r,"fact_id",row.first),order(r)});if(selected_version==2){auto parsed=decode_social_event_original_application(field(r,"original_application",row.first));if(!parsed.ok)return {false,{},parsed.error};s.events.find(row.first)->original_application=std::move(parsed.value);}}if(selected_version==2){for(const auto&row:object(field(social,"relation_results","social"),"social/relation_results")){auto result=decode_social_relation_result(row.second);if(!result.ok)return {false,{},result.error};if(row.first!=result.value.result_id||!s.relation_results.insert(row.first,std::move(result.value)))fail("OriginalRelationResultKeyMismatch",row.first);}}auto selected=validate_social_relation_state_selection(s,selected_version);if(!selected.ok)return {false,{},selected.error};return {true,std::move(s),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<SocialState> decode_social_seed(const BoundaryValue& world){return decode_social_seed(world,1);}
Status emit_social_state_fields(ProjectionWriter& out,const SocialState& s,Integer selected_version){
    auto selected=validate_social_relation_state_selection(s,selected_version);if(!selected.ok)return selected;
    out.object("relations",[&](auto& w){for(const auto& row:s.relations.rows()){w.object(row.first,[&](auto& c){const auto& r=row.second;if(r.id)c.field("id",*r.id);c.field("from_actor",r.from_actor);c.field("to_actor",r.to_actor);c.field("trust",r.trust);c.field("affinity",r.affinity);return c.order_fields(r.field_order);});if(!w.status().ok)break;}return w.status();});
    out.object("social",[&](auto& w){w.field("last_tick",s.last_tick);
        w.object("memories",[&](auto& c){for(const auto& row:s.memories.rows()){c.object(row.first,[&](auto& x){for(const auto& item:row.second.rows()){x.object(item.first,[&](auto& y){y.field("learned_tick",item.second.learned_tick);y.field("source_actor_id",item.second.source_actor_id);return y.order_fields(item.second.field_order);});if(!x.status().ok)break;}return x.status();});if(!c.status().ok)break;}return c.status();});
        w.object("events",[&](auto& c){for(const auto& row:s.events.rows()){c.object(row.first,[&](auto& x){const auto& e=row.second;x.field("id",e.id);x.field("kind",e.kind);x.field("tick",e.tick);x.field("place_id",e.place_id);x.field("actor_id",e.actor_id);x.field("target_actor_id",e.target_actor_id);x.field("item_id",e.item_id);x.field("quantity",e.quantity);x.field("reason",e.reason);x.field("fact_id",e.fact_id);if(selected_version==2)x.object("original_application",[&](auto&y){return emit_social_event_original_application_fields(y,*e.original_application);});return x.order_fields(e.field_order);});if(!c.status().ok)break;}return c.status();});
        if(s.dynamic)w.object("dynamic",[&](auto& c){return social_time2_version(s.dynamic->version)?emit_dynamic_social_time2_fields(c,*s.dynamic):emit_dynamic_social_fields(c,*s.dynamic);});if(selected_version==2)w.object("relation_results",[&](auto&c){for(const auto&row:s.relation_results.rows()){c.object(row.first,[&](auto&x){return emit_social_relation_result_fields(x,row.second);});if(!c.status().ok)break;}return c.status();});return w.order_fields(s.field_order);
    });return out.status();
}
Status emit_social_state_fields(ProjectionWriter&w,const SocialState&s){return emit_social_state_fields(w,s,1);}
BoundaryValue encode_social_state(const SocialState& s,Integer selected_version){BoundaryValue value;BoundaryProjectionWriter writer(value);auto status=writer.object("",[&](auto& out){return emit_social_state_fields(out,s,selected_version);});if(status.ok)status=writer.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}

BoundaryValue encode_social_state(const SocialState&s){return encode_social_state(s,1);}
namespace {
// typed有序表写键和值；恢复构造新索引，不按键排序或容忍重复键。
template<class T,class F>Status visit_table(CodecVisitor& c,std::string_view name,OrderedTable<T>& table,F visit){

    auto row_visit=[&](CodecVisitor& v,auto& row){return v.object("row",[&](CodecVisitor& e){e.field("key",row.first);return visit(e,row.second);});};
    // Preserve the original object("row") wire, not Common's distinct entry
    // wrapper. Only the sole Common staged/adopt mechanism owns collection.
    return common_checkpoint::table_rows(c,name,table,"DuplicateCheckpointKey",row_visit);
}
}
Status visit_social_checkpoint(CodecVisitor& c,SocialState& s,Integer selected_version){if(selected_version!=1&&selected_version!=2)return c.reject("UnsupportedOriginalSocialVersion");if(c.reading())s.original_relation_version=selected_version;else{auto selected=validate_social_relation_state_selection(s,selected_version);if(!selected.ok)return selected;}c.field("last_tick",s.last_tick);common_checkpoint::strings(c,"field_order",s.field_order);visit_table(c,"relations",s.relations,[](CodecVisitor& v,RelationRecord& r){v.optional("id",r.id,[](CodecVisitor& x,StableId& id){return x.field("value",id);});v.field("from_actor",r.from_actor);v.field("to_actor",r.to_actor);v.field("trust",r.trust);v.field("affinity",r.affinity);return common_checkpoint::strings(v,"field_order",r.field_order);});visit_table(c,"memories",s.memories,[](CodecVisitor& v,OrderedTable<SocialMemory>& ms){return visit_table(v,"known",ms,[](CodecVisitor& x,SocialMemory& m){x.field("learned_tick",m.learned_tick);x.field("source_actor_id",m.source_actor_id);return common_checkpoint::strings(x,"field_order",m.field_order);});});visit_table(c,"events",s.events,[selected_version](CodecVisitor& v,SocialEvent& e){v.field("id",e.id);v.field("kind",e.kind);v.field("tick",e.tick);v.field("place_id",e.place_id);v.field("actor_id",e.actor_id);v.field("target_actor_id",e.target_actor_id);v.field("item_id",e.item_id);v.field("quantity",e.quantity);v.field("reason",e.reason);v.field("fact_id",e.fact_id);common_checkpoint::strings(v,"field_order",e.field_order);if(selected_version==2){if(v.reading()){if(!prepare_checkpoint_default_values<SocialEventOriginalApplication>(v).ok)return v.status();e.original_application.emplace();}if(!e.original_application)return v.reject("OriginalSocialEventApplicationRequired");v.object("original_application",[&](auto&x){return visit_social_event_original_application(x,*e.original_application);});}return v.status();});if(selected_version==2)visit_table(c,"relation_results",s.relation_results,[](CodecVisitor&v,SocialRelationResult&r){return visit_social_relation_result(v,r);});if(!c.status().ok)return c.status();return validate_social_relation_state_selection(s,selected_version);}
Status visit_social_checkpoint(CodecVisitor&c,SocialState&s){return visit_social_checkpoint(c,s,1);}
